using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;
public static class TrimCaveHillside{public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/LakeWoods.unity");var road=UnityEngine.Object.FindAnyObjectByType<RaceDirector>().road;road.Initialize();var samples=new List<Vector3>();for(float s=0;s<road.Length;s+=1)samples.Add(road.At(s,out _));int removed=0;foreach(string name in new[]{"Ground_Echo wooded hillside","Echo eroded hillside face 0","Echo eroded hillside face 140"}){var g=GameObject.Find(name);var m=g.GetComponent<MeshFilter>().sharedMesh;var v=m.vertices;var near=v.Select(p=>samples.Min(q=>Vector2.Distance(new(p.x,p.z),new(q.x,q.z)))<8).ToArray();var tr=m.triangles;var keep=new List<int>();for(int i=0;i<tr.Length;i+=3){if(near[tr[i]]||near[tr[i+1]]||near[tr[i+2]]){removed++;continue;}keep.AddRange(new[]{tr[i],tr[i+1],tr[i+2]});}if(name.Contains("face"))for(int i=0;i<v.Length;i+=5)v[i].y-=.35f;m.vertices=v;m.triangles=keep.ToArray();m.RecalculateNormals();EditorUtility.SetDirty(m);g.GetComponent<MeshCollider>().sharedMesh=null;g.GetComponent<MeshCollider>().sharedMesh=m;}EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();return "Removed "+removed+" terrain-cover triangles within main trail clearance";}}
